  const safe = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const memory = {};
  const rawRead = (key, fallback) => { try { const stored = localStorage.getItem(key); return stored === null ? fallback : JSON.parse(stored); } catch { return key in memory ? memory[key] : fallback; } };
  const rawWrite = (key, value) => { memory[key] = value; try { localStorage.setItem(key, JSON.stringify(value)); } catch {} };
  const role = rawRead('para-v2-role', 'anya.demo');
  const read = (key, fallback) => rawRead('para-student-v1-' + role + '-' + key, fallback);
