  const announce = message => { const target = $('#toast'); if (!target) return; target.textContent = message; target.hidden = false; clearTimeout(window.paraToast); window.paraToast = setTimeout(() => { target.hidden = true; }, 4500); };
  const prefs = () => rawRead('para-student-v1-comfort', {large:false, motion:false, density:'comfortable'});
  const applyComfort = () => { const value = prefs(); document.documentElement.classList.toggle('para-large-text', !!value.large); document.documentElement.classList.toggle('para-reduce-motion', !!value.motion); document.documentElement.dataset.density = value.density === 'compact' ? 'compact' : 'comfortable'; };
