    $('#meal-saved').addEventListener('click', event => { if (!event.target.closest('[data-undo-meal]')) return; const previous = read('meal-undo', null); if (!previous) return; write('meal', previous.items); write('meal-saved', !!previous.saved); write('meal-undo', null); render(); $('#meal-saved').textContent = 'Набор восстановлен' + (previous.saved ? ' вместе с сохранённым планом.' : '. Можно продолжить выбирать блюда.'); $('#save-meal').focus(); announce('Набор восстановлен'); });
