      let message = !file ? 'Выберите файл работы' : !/\.(pdf|docx?|txt)$/i.test(file.name) ? 'Подойдёт PDF, DOC, DOCX или TXT' : file.size > 10 * 1024 * 1024 ? 'Файл больше 10 МБ. Выберите файл поменьше.' : file.size === 0 ? 'Файл пустой. Выберите готовую работу.' : '';
