    $('#consultation-form').addEventListener('submit', event => { event.preventDefault(); const topic = $('#consultation-topic'), invalid = !topic.value.trim(); $('#consultation-error').hidden = !invalid; topic.setAttribute('aria-invalid', String(invalid)); if (invalid) { topic.focus(); return; } write('consultation', {slot:$('#consultation-slot').value,topic:topic.value.trim()}); write('consultation-undo', null); render(); announce('Демо-запись на консультацию сохранена'); });
